/**
 * Types for the vendored Primus client (primus-websockets2.js, generated by the Primus server, see readme.md).
 * Only the API the app uses is declared. `Out` is what the app writes, `In` what the server sends.
 */
export interface IPrimusSocket<Out = unknown, In = unknown> {
  /** Send data to the server (queued while offline). Returns false when the connection is closed */
  write(data: Out): boolean
  on(event: 'data', listener: (data: In) => void): this
  on(event: 'error', listener: (error: Error) => void): this
  on(event: 'open' | 'end' | 'close' | 'reconnect' | 'reconnected' | 'online' | 'offline', listener: () => void): this
  /** Close the connection */
  end(data?: Out): this
}

interface IPrimusStatic {
  /** Connect to a Primus server (`new Primus(url, options)`) */
  connect<Out = unknown, In = unknown>(url: string, options?: Record<string, unknown>): IPrimusSocket<Out, In>
}

declare const Primus: IPrimusStatic
export default Primus
